		void AutoPickButton_Click(object sender, EventArgs e)
		{
			HandleAutoPickButtonClick();
		}

		void HandleAutoPickButtonClick()
		{
			if (Pick.WP_PickOption != WhsPickOption.Codes.Auto)
			{
				Globals.Message.ShowError(
					Res.GetString("d0c10ee1-764a-48a1-8e1a-b62657bc9d71", "You cannot auto pick because this pick has a Pick Option of Manual"),
					Res.GetString("dcbe8650-7cd3-4c6b-879c-fc57c685c925", "Error"));
			}
			else
			{
				new PickManagerForWhsPick((ZForm)ParentForm, Pick).PickOrders();
			}
		}

		void CancelPickButton_Click(object sender, EventArgs e)
		{
			HandleCancelPickButtonClick();
		}

		void HandleCancelPickButtonClick()
		{
			using (new ZWaitCursorChanger(ParentForm))
			{
				var errorMessage = Pick.GetIsCancellableErrorMessage();
				var isCancellable = errorMessage.IsEmpty;
				if (!isCancellable)
				{
					Globals.Message.ShowError(errorMessage);
				}
				else
				{
					var success = Pick.CancelPick();
					if (success)
					{
						Globals.Message.ShowInformation(ReleaseEntryForm.PickCancelledConfirmationMsg, Res.GetString("f3effa20-f354-41af-84a0-c8edb611c04a", "Confirmation"));
					}
					else
					{
						Globals.Message.ShowError(
							Res.GetString("1e1faa4d-96ae-4e70-af8f-fea818266c5e", "An error occurred during Cancellation."),
							Res.GetString("dcbe8650-7cd3-4c6b-879c-fc57c685c925", "Error"));
					}
				}
			}
		}

		void ReleaseButton_Click(object sender, EventArgs e)
		{
			HandleReleaseButtonClick();
		}

		void HandleReleaseButtonClick()
		{
			if (Pick.HasChanges)
			{
				Globals.Message.ShowWarning(Res.GetString("ef220d69-d765-4d33-b5cc-f7c9925f7fcc", "Please save this Pick before going to the Release Form."));
			}
			else if (Pick.Orders.Count == 0)
			{
				Globals.Message.ShowWarning(Res.GetString("9dbea662-bb03-41a9-927e-90a52eb025e2", "Please attach an order to the Pick before going to the Release Form."));
			}
			else
			{
				var controller = GetController(ControllerIDs.WhsRelease);
				var releaseEntryForm = (ReleaseEntryForm)controller.ShowEditForm(Pick);

				var currentOrder = SelectedOrders.Length == 1 ? SelectedOrders.Single() : null;
				if (!(currentOrder is null))
				{
					releaseEntryForm.SetInitialOrderToSelectInGrid(currentOrder.PK);
				}
			}
		}

